import {RECIPES,CASE_PACK_KIND,CASE_LIMITS,emptyCasePack,validateCase,validateCasePack,mergeCasePacks,filterCases,publicURL} from './case-model.js';
import {esc,uid,THEMES,BLOCKS,generateDocument} from './engine.js';
const CASE_STORAGE='design-atlas.case-pack.v2';
const registry={blocks:BLOCKS,themes:THEMES};
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const copyJSON=v=>JSON.parse(JSON.stringify(v));
const labels={type:'全部类型',style:'全部风格',pattern:'全部模式'};
const link=(u,label,cls='')=>`<a class="${cls}" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
export function backupUnreadablePack(storage,raw){const key=CASE_STORAGE+'.recovery.'+Date.now()+'-'+uid();storage.setItem(key,raw);if(storage.getItem(key)!==raw)throw Error('恢复备份校验失败，原数据未覆盖');storage.setItem(CASE_STORAGE+'.recovery.latest',key);return key;}
export function createCaseUI(bridge){
 let builtins=[],pack=emptyCasePack(),loadWarning='',visible=false,preview=null,packUndo=null,recoveryRaw=null,recoveryBackup='';
 const view={q:'',type:'',style:'',pattern:'',sort:'recommended',favoriteOnly:false,page:1,compare:[],tab:'cases'};
 const dialog=document.createElement('dialog');dialog.id='case-dialog';dialog.className='case-dialog';document.body.append(dialog);
 const file=document.createElement('input');file.type='file';file.accept='.json,application/json';file.hidden=true;document.body.append(file);
 try{const key=localStorage.getItem(CASE_STORAGE+'.recovery.latest');if(key?.startsWith(CASE_STORAGE+'.recovery.'))recoveryBackup=key;const raw=localStorage.getItem(CASE_STORAGE);try{if(raw)pack=validateCasePack(JSON.parse(raw),registry)}catch{recoveryRaw=raw;loadWarning='先前的案例扩展数据无法读取，原始数据仍保留。第一次修改前会创建独立恢复备份；备份失败时不会覆盖。'}}catch{loadWarning='无法读取浏览器存储。修改需要成功保存后才会生效。';}
 const recipes=()=>[...RECIPES,...pack.recipes];
 const items=()=>[...builtins,...pack.cases];
 const find=id=>items().find(c=>c.id===id);
 const isFavorite=id=>pack.user.favorites.includes(id);
 const notify=()=>{bridge.changed();if(visible)render();};
 function commit(next,message,{record=true}={}){try{const clean=validateCasePack(next,registry),json=JSON.stringify(clean);if(new Blob([json]).size>CASE_LIMITS.bytes)throw Error('扩展数据超过 4 MiB，请分成较小的案例包。');if(recoveryRaw!==null){recoveryBackup=backupUnreadablePack(localStorage,recoveryRaw);recoveryRaw=null}localStorage.setItem(CASE_STORAGE,json);if(record)packUndo=copyJSON(pack);pack=clean;loadWarning='';bridge.changed();if(message)bridge.toast(message);return true}catch(e){bridge.toast('未保存：'+e.message,true);return false}}
 function toggle(id){const next=copyJSON(pack);next.user.favorites=isFavorite(id)?next.user.favorites.filter(x=>x!==id):[...next.user.favorites,id];if(commit(next)){notify();$$('[data-case-favorite]').filter(b=>b.dataset.caseFavorite===id).forEach(b=>{b.textContent=isFavorite(id)?'♥':'♡';b.setAttribute('aria-pressed',String(isFavorite(id)))})}}
 function close(){dialog.close();document.body.style.overflow=$$('dialog[open]').length?'hidden':'';preview=null;}
 function show(html){dialog.innerHTML=html;if(!dialog.open)dialog.showModal();document.body.style.overflow='hidden';dialog.scrollTop=0;}
 const top=(eyebrow,title,description='')=>`<div class="dialog-top"><div><span class="eyebrow">${eyebrow}</span><h2>${esc(title)}</h2>${description?`<p>${esc(description)}</p>`:''}</div><button class="icon-btn" data-case-action="close" aria-label="关闭案例窗口">×</button></div>`;
 function recipeFor(c){return recipes().find(r=>r.id===c.recipe)||RECIPES[0]}
 function illustration(c){const theme=THEMES.find(t=>t.id===c.theme)||THEMES[0];const r=recipeFor(c);return `<div class="case-illustration layout-${esc(r.id.replace(/^user-.*/, 'custom'))}" style="--case-bg:${theme.bg};--case-ink:${theme.ink};--case-accent:${theme.accent};--case-surface:${theme.surface}"><div class="case-wire-nav"><b>✳</b><i></i><i></i><i></i></div><div class="case-wire-content"><div class="case-wire-heading"><span>${esc(c.type)}</span><b>${r.id==='digital-garden'?'Notes &<br>small ideas.':r.id==='portfolio-index'||r.id==='developer-home'?'A little about<br>what I make.':r.id==='minimal-profile'?'Hello.<br>I’m a maker.':r.id==='creative-studio'||r.id==='editorial-story'?'Ideas.<br>Made visible.':'Make room<br>for better work.'}</b><i></i><em></em></div><div class="case-wire-panels">${[0,1,2,3].map(i=>`<div><span>${['✳','↗','◎','◈'][i]}</span><i></i><i></i></div>`).join('')}</div></div><div class="case-illustration-label">布局示意 · 原创配方</div></div>`;}
 function card(c){return `<article class="case-card"><button class="case-art-button" data-case-open="${esc(c.id)}" aria-label="查看 ${esc(c.name)} 案例">${illustration(c)}</button><div class="case-card-body"><div class="case-card-meta"><span>${esc(c.type)} / ${esc(c.category)}</span><button data-case-favorite="${esc(c.id)}" class="case-heart" aria-label="收藏 ${esc(c.name)}" aria-pressed="${isFavorite(c.id)}">${isFavorite(c.id)?'♥':'♡'}</button></div><h3><button data-case-open="${esc(c.id)}">${esc(c.name)} <span>↗</span></button></h3><p>${esc(c.summary)}</p><div class="case-tags">${c.patterns.slice(0,2).map(t=>`<button data-case-pattern="${esc(t)}">${esc(t)}</button>`).join('')}</div><div class="case-card-bottom"><button class="case-text-button" data-case-open="${esc(c.id)}">拆解与试用 →</button><button class="case-compare-toggle ${view.compare.includes(c.id)?'active':''}" data-case-compare="${esc(c.id)}" aria-pressed="${view.compare.includes(c.id)}">${view.compare.includes(c.id)?'✓ 已选':'＋ 对比'}</button></div></div></article>`;}
 const matched=()=>filterCases(items(),view,pack.user.favorites);
 function counter(){const all=items(),personal=all.filter(c=>['个人网站','作品集'].includes(c.type)).length;return `<div class="case-metrics"><div><b>${all.length}</b><span>公开网站案例</span></div><div><b>${personal}</b><span>个人网站与作品集</span></div><div><b>${all.filter(c=>c.type==='产品页').length}</b><span>产品与工具页面</span></div><div><b>${recipes().length}</b><span>可组合设计配方</span></div></div>`;}
 function filters(){return `<div class="case-filter-controls"><label class="case-search"><span>⌕</span><input type="search" id="case-search" placeholder="搜索名称、模式、设计思路…" aria-label="搜索网站案例" value="${esc(view.q)}"><kbd>/</kbd></label>${['type','style','pattern'].map(key=>{const values=[...new Set(items().flatMap(c=>key==='type'?[c.type]:c[key==='style'?'styles':'patterns']))].sort((a,b)=>a.localeCompare(b,'zh-CN'));return `<label class="case-select"><span class="sr-only">${labels[key]}</span><select data-case-filter="${key}" aria-label="${labels[key]}"><option value="">${labels[key]}</option>${values.map(t=>`<option ${view[key]===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}).join('')}</div><div class="case-results-line"><div><b id="case-result-count">${matched().length}</b> 个匹配案例 <span>· 多个筛选条件同时生效</span></div><div><button class="case-filter-favorites ${view.favoriteOnly?'active':''}" data-case-action="favorites" aria-pressed="${view.favoriteOnly}">♡ 只看收藏</button><label class="sr-only" for="case-sort">案例排序</label><select id="case-sort" data-case-filter="sort"><option value="recommended" ${view.sort==='recommended'?'selected':''}>推荐顺序</option><option value="personal" ${view.sort==='personal'?'selected':''}>个人网站优先</option><option value="name" ${view.sort==='name'?'selected':''}>名称 A–Z</option><option value="favorites" ${view.sort==='favorites'?'selected':''}>收藏优先</option></select><button class="case-text-button" data-case-action="reset">重置筛选</button></div></div>`;}
 function pageGrid(){const list=matched(),pages=Math.max(1,Math.ceil(list.length/12));view.page=Math.max(1,Math.min(view.page,pages));return `<div class="case-grid">${list.slice((view.page-1)*12,view.page*12).map(card).join('')||'<div class="case-empty"><span>⌕</span><h3>这组条件还没有对应案例。</h3><p>减少一个条件，或者加入你自己的参考网站。</p><button class="secondary-button" data-case-action="reset">重置筛选</button></div>'}</div><div class="case-pagination"><button data-case-page="${view.page-1}" ${view.page===1?'disabled':''}>← 上一页</button><span>${view.page} / ${pages} · ${list.length} 项</span><button data-case-page="${view.page+1}" ${view.page===pages?'disabled':''}>下一页 →</button></div>`;}
 function compareTray(){const chosen=view.compare.map(find).filter(Boolean);return chosen.length?`<aside class="case-compare-tray" aria-label="案例对比栏"><div><b>一起看，差异更清楚。</b><span>${chosen.map(c=>`<button data-case-compare="${esc(c.id)}" aria-label="移除对比 ${esc(c.name)}">${esc(c.name)} ×</button>`).join('')}</span></div><button class="primary-button" data-case-action="compare" ${chosen.length<2?'disabled':''}>比较 ${chosen.length} 个案例 ↗</button></aside>`:'';}
 function recipeCards(){return `<div class="recipe-intro"><div><h2>把设计思路，拼成自己的页面。</h2><p>配方只组合本站原创模块。先试布局，再决定主题；追加时保留现有页面的主题和内容。</p></div><button class="secondary-button" data-case-action="capture">＋ 保存当前页面为配方</button></div><div class="recipe-grid">${recipes().map((r,i)=>`<article class="recipe-card"><span class="recipe-number">${String(i+1).padStart(2,'0')} / ${r.id.startsWith('user-')?'MY RECIPE':'DESIGN RECIPE'}</span><h3>${esc(r.name)}</h3><p>${esc(r.description)}</p><ol>${r.blocks.map(b=>`<li>${esc(BLOCKS.find(x=>x.id===b.type)?.name||b.type)}</li>`).join('')}</ol><div class="recipe-card-actions"><button class="secondary-button" data-case-recipe-preview="${esc(r.id)}">预览配方</button><button class="primary-button" data-case-recipe-apply="${esc(r.id)}" data-case-mode="append">追加到页面 ＋</button>${r.id.startsWith('user-')?`<button class="case-text-button" data-recipe-remove="${esc(r.id)}">移除配方</button>`:''}</div></article>`).join('')}</div>`;}
 function render(){visible=true;const main=bridge.root;main.innerHTML=`<div class="case-heading"><div class="page-eyebrow"><i></i>THE WEB, THROUGH A DESIGNER’S EYES</div><div class="case-title-row"><div><h1>好网站，<em>值得拆开看。</em></h1><p>从个人角落到产品舞台。收藏一种思路，试试不同组合，再带走自己的代码。</p></div><div class="case-heading-mark" aria-hidden="true">↗</div></div>${counter()}</div>${loadWarning?`<div class="restore-banner">${esc(loadWarning)} <button data-case-action="raw-backup">导出原始备份</button></div>`:''}<div class="case-toolbar"><div class="case-section-tabs"><button data-case-tab="cases" class="${view.tab==='cases'?'active':''}" aria-pressed="${view.tab==='cases'}">网站案例 <span>${items().length}</span></button><button data-case-tab="recipes" class="${view.tab==='recipes'?'active':''}" aria-pressed="${view.tab==='recipes'}">设计配方 <span>${recipes().length}</span></button><button data-case-tab="extend" class="${view.tab==='extend'?'active':''}" aria-pressed="${view.tab==='extend'}">扩充我的库</button></div><button class="secondary-button" data-case-action="add">＋ 添加案例</button></div>${view.tab==='cases'?`${filters()}<div class="case-source-note"><b>先看思路，再试变化。</b>卡片为原创布局示意；原站链接、已核实内容与适配建议在详情中分开展示。</div><div id="case-grid-region">${pageGrid()}</div>`:view.tab==='recipes'?recipeCards():extensionPanel()}<div id="case-tray-region">${compareTray()}</div>`;}
 function updateGrid(){const region=$('#case-grid-region');if(region){region.innerHTML=pageGrid();$('#case-result-count').textContent=matched().length;}const tray=$('#case-tray-region');if(tray)tray.innerHTML=compareTray();}
 function extensionPanel(){return `<div class="case-extension-grid"><section class="case-extension-panel"><span class="eyebrow">YOUR OWN LIBRARY</span><h2>让案例库，跟着你生长。</h2><p>自己的案例、配方、收藏和学习笔记都保存在此浏览器。导出一个 JSON 扩展包，就可以迁移到另一台设备。</p><div class="extension-stats"><b>${pack.cases.length}<small>我的案例</small></b><b>${pack.recipes.length}<small>我的配方</small></b><b>${Object.values(pack.user.notes).filter(Boolean).length}<small>学习笔记</small></b></div><div class="extension-actions"><button class="primary-button" data-case-action="export">导出我的扩展包 ↓</button><button class="secondary-button" data-case-action="import">导入扩展包 ↑</button><button class="secondary-button" data-case-action="sample">下载示例包</button>${recoveryBackup?'<button class="secondary-button" data-case-action="recovery-backup">导出恢复备份</button>':''}<button class="secondary-button" data-case-action="undo-pack" ${packUndo?'':'disabled'}>撤销最近一次库修改</button></div><p class="source-note">导入会完整校验，同 ID 案例保留本地条目，配方内容冲突会拒绝导入；一次失败不会覆盖现有案例。最多 500 个自定义案例、100 个配方、4 MiB。扩展包使用声明式数据。</p></section><section class="case-extension-panel"><span class="eyebrow">THREE SIMPLE STEPS</span><h2>从发现，到自己的作品。</h2><ol class="extension-steps"><li><b>保存一个网站</b><p>填写链接、借鉴要点、风格与模式，为它选一个原创配方。</p></li><li><b>试着组合</b><p>在拼装台调整图层与主题，再把页面保存成自己的配方。</p></li><li><b>把经验带走</b><p>导出扩展包，分享的是你的整理与配方，不包含原站素材或源码。</p></li></ol><button class="case-text-button" data-case-action="schema">查看扩展协议 →</button></section></div>${pack.cases.length?`<div class="my-cases"><h2>我的案例</h2>${pack.cases.map(c=>`<div><span>${esc(c.name)}</span><small>${esc(c.type)}</small><button class="case-text-button" data-case-edit="${esc(c.id)}">编辑</button><button class="case-text-button" data-case-remove="${esc(c.id)}">移除</button><button class="case-text-button" data-case-open="${esc(c.id)}">查看 ↗</button></div>`).join('')}</div>`:''}`;}
 function recipeSelect(selected,id='case-recipe-select'){return `<select id="${id}" aria-label="原创布局配方">${recipes().map(r=>`<option value="${esc(r.id)}" ${r.id===selected?'selected':''}>${esc(r.name)} · ${r.blocks.length} 模块</option>`).join('')}</select>`;}
 function themeSelect(selected,id='case-theme-select'){return `<select id="${id}" aria-label="建议主题">${THEMES.map(t=>`<option value="${t.id}" ${t.id===selected?'selected':''}>${esc(t.name)}</option>`).join('')}</select>`;}
 function selectedRecipe(){const source=recipes().find(r=>r.id===$('#case-recipe-select',dialog)?.value)||preview.recipe;const theme=$('#case-theme-select',dialog)?.value;return {...copyJSON(source),theme:!preview.case&&!preview.themeTouched&&typeof source.theme==='object'?copyJSON(source.theme):theme||source.theme};}
 function previewDoc(){if(!preview)return;const frame=$('#case-live-preview',dialog);if(frame)frame.srcdoc=generateDocument(bridge.makeProject(selectedRecipe()));}
 function open(id){const c=find(id);if(!c)return;const r=recipeFor(c);preview={case:c,recipe:r};const note=pack.user.notes[c.id]||'';
 show(top('WEBSITE STUDY / ORIGINAL ADAPTATION',c.name,c.summary)+`<div class="case-detail-layout"><div class="case-study"><div class="case-study-top"><span class="case-type-pill">${esc(c.type)}</span>${link(c.url,'访问原站','case-external')}<button class="case-heart" data-case-favorite="${esc(c.id)}" aria-label="收藏 ${esc(c.name)}" aria-pressed="${isFavorite(c.id)}">${isFavorite(c.id)?'♥':'♡'}</button></div><div class="case-evidence"><b>${c.evidence.level==='browser-sampled'?'已抽样查看真实布局':c.evidence.level==='content-reviewed'?'已读取原站内容':'用户整理 · 尚未核实'}</b><span>${esc(c.evidence.checkedAt)}</span><p>${esc(c.evidence.notes)}</p>${c.evidence.observations?.length?`<ul>${c.evidence.observations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</div><h3>可以借鉴什么</h3><ol class="takeaway-list">${c.takeaways.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="case-tags">${[...c.styles,...c.patterns].map(t=>`<span>${esc(t)}</span>`).join('')}</div><h3>使用时想一想</h3><p class="case-study-copy">${esc(c.caution||'先确认内容和用户目标，再选择合适的布局与交互。')}</p><label class="case-note-label" for="case-note">我的学习笔记</label><textarea id="case-note" maxlength="4000" placeholder="这个模式适合我项目里的哪个部分？">${esc(note)}</textarea><div class="case-note-actions"><button class="secondary-button" data-case-save-note="${esc(c.id)}">保存笔记</button>${c.id.startsWith('user-')?`<button class="case-text-button" data-case-edit="${esc(c.id)}">编辑案例</button>`:''}<button class="case-text-button" data-case-compare="${esc(c.id)}">${view.compare.includes(c.id)?'从对比移除':'加入对比'}</button></div><p class="source-note">${esc(c.rights.note)} 右侧配方由工作台原创，可继续编辑并按 MIT 导出。</p></div><div class="case-adaptation"><div class="case-preview-heading"><div><b>试试你的版本</b><span>原创适配预览 · 非原站复制</span></div><div class="case-device-buttons"><button data-case-device="desktop" aria-pressed="true">桌面</button><button data-case-device="mobile" aria-pressed="false">手机</button></div></div><div class="case-preview-options"><label>布局配方${recipeSelect(r.id)}</label><label>建议主题${themeSelect(c.theme)}</label></div><div class="case-preview-stage" data-device="desktop"><iframe id="case-live-preview" title="${esc(c.name)}的原创适配预览" sandbox="allow-scripts" referrerpolicy="no-referrer"></iframe></div><div class="case-apply-options"><button class="secondary-button" data-case-apply="theme">只应用主题</button><button class="secondary-button" data-case-apply="append">追加这些模块</button><button class="primary-button" data-case-apply="replace">以此生成页面 ↗</button><button class="case-text-button" data-case-action="code">复制配方源码</button></div><p class="source-note">生成页面会替换当前图层，可一步撤销。追加会保留现有主题。建议主题用于探索，并非原站色值测量。</p></div></div>`);previewDoc();}
 function openRecipe(id){const r=recipes().find(x=>x.id===id);if(!r)return;preview={recipe:r};const theme=typeof r.theme==='string'?r.theme:r.theme.id;show(top('ORIGINAL RECIPE / EDITABLE & EXPORTABLE',r.name,r.description)+`<div class="recipe-full-preview"><div class="case-preview-options"><label>布局配方${recipeSelect(r.id)}</label><label>主题方向${themeSelect(theme)}</label></div><p class="source-note">原创配方预览。点击“以此生成页面”后可在拼装台逐块编辑，或直接复制源代码。</p><div class="case-preview-stage"><iframe id="case-live-preview" title="${esc(r.name)}原创配方预览" sandbox="allow-scripts"></iframe></div><div class="case-apply-options"><button class="secondary-button" data-case-apply="theme">只应用主题</button><button class="secondary-button" data-case-apply="append">追加这些模块</button><button class="primary-button" data-case-apply="replace">以此生成页面 ↗</button><button class="case-text-button" data-case-action="code">复制配方源码</button></div></div>`);previewDoc();}
 function compare(){const chosen=view.compare.map(find).filter(Boolean);if(chosen.length<2)return;show(top('SIDE BY SIDE / PICK WHAT WORKS','并排看，找到适合你的部分。','主题与结构可以分别应用，再回到拼装台继续组合。')+`<div class="case-comparison" style="--compare-count:${chosen.length}">${chosen.map(c=>`<article class="case-compare-column">${illustration(c)}<div class="case-compare-column-body"><span class="eyebrow">${esc(c.type)}</span><h3>${esc(c.name)}</h3>${link(c.url,'查看原站','case-external')}<h4>页面目标</h4><p>${esc(c.summary)}</p><h4>模式与风格</h4><div class="case-tags">${[...c.styles,...c.patterns].map(x=>`<span>${esc(x)}</span>`).join('')}</div><h4>借鉴建议</h4><ul>${c.takeaways.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>原创布局配方</h4><ol class="compare-recipe">${recipeFor(c).blocks.map(b=>`<li>${esc(BLOCKS.find(x=>x.id===b.type)?.name||b.type)}</li>`).join('')}</ol><h4>适用边界</h4><p>${esc(c.caution)}</p><div class="case-compare-actions"><button class="secondary-button" data-case-compare-apply="${esc(c.id)}" data-case-mode="theme">用这个建议主题</button><button class="primary-button" data-case-compare-apply="${esc(c.id)}" data-case-mode="append">追加这个结构</button><button class="case-text-button" data-case-open="${esc(c.id)}">打开详情与预览 ↗</button></div></div></article>`).join('')}</div>`);}
 function edit(id){const c=id?find(id):null;const field=(key,label,value='',extra='')=>`<label>${label}<input name="${key}" value="${esc(value)}" ${extra}></label>`;show(top('GROW YOUR LIBRARY',c?'编辑我的案例':'保存一个值得借鉴的网站','只保存你的整理与来源链接；不抓取或上传网站资产。')+`<form id="case-edit-form" class="case-edit-form" data-edit-id="${esc(c?.id||'')}"><div class="case-form-grid">${field('name','网站名称',c?.name,'required maxlength="100"')}${field('url','公开网站链接',c?.url,'required type="url" placeholder="https://…" maxlength="2048"')}<label>网站类型<select name="type">${['个人网站','作品集','产品页','工作室'].map(t=>`<option ${c?.type===t?'selected':''}>${t}</option>`).join('')}</select></label>${field('category','内容分类',c?.category||'我的参考','required maxlength="60"')}</div><label>一句话说明<textarea name="summary" required maxlength="1200" placeholder="这个页面如何组织内容，什么地方值得借鉴？">${esc(c?.summary||'')}</textarea></label><div class="case-form-grid">${field('styles','风格（逗号分隔）',c?.styles.join(', ')||'极简','maxlength="500"')}${field('patterns','设计模式（逗号分隔）',c?.patterns.join(', ')||'目录导航','maxlength="500"')}${field('tags','标签（逗号分隔）',c?.tags.join(', ')||'个人收藏','maxlength="500"')}<label>原创布局配方${recipeSelect(c?.recipe||'minimal-profile','edit-case-recipe')}</label><label>建议主题${themeSelect(c?.theme||'atelier','edit-case-theme')}</label></div><label>借鉴要点（每行一条）<textarea name="takeaways" maxlength="2400">${esc(c?.takeaways.join('\n')||'')}</textarea></label><label>适用边界<textarea name="caution" maxlength="1000">${esc(c?.caution||'')}</textarea></label><div class="case-form-footer"><span>保存后可随时编辑，或导出 JSON 扩展包。</span><button class="primary-button" type="submit">保存案例 ✓</button></div></form>`);}
 function capture(){const p=bridge.getProject();if(!p.blocks.some(b=>!b.hidden)){bridge.toast('先在拼装台添加一些可见模块。',true);return}show(top('REUSABLE BY DESIGN','把当前页面保存为配方','保留可见模块的顺序、文字与主题。不包含自定义 CSS、隐藏模块和演示运行状态。')+`<form id="recipe-capture-form" class="case-edit-form"><label>配方名称<input name="name" maxlength="100" required value="${esc(p.name)}"></label><label>用途说明<textarea name="description" maxlength="500" placeholder="什么场景适合这组结构？"></textarea></label><p class="source-note">${p.blocks.filter(b=>!b.hidden).length} 个可见模块 · 每份配方最多 40 个模块</p><button class="primary-button" type="submit">保存为我的配方 ✓</button></form>`);}
 function importPack(raw){try{const incoming=validateCasePack(raw,registry),merged=mergeCasePacks(pack,incoming,registry);if(commit(merged.pack,`扩展包已导入：${incoming.cases.length} 个案例、${incoming.recipes.length} 个配方；${merged.skipped} 个重复 ID 保留原项。`)){view.tab='extend';close();bridge.navigate();}}catch(e){bridge.toast('导入失败：'+e.message,true)}}
 function sample(){const r={...copyJSON(RECIPES[0]),id:'user-example-recipe',name:'我的作品展示配方'};const c={id:'user-example-site',name:'我的网站参考',url:'https://example.com/',type:'个人网站',category:'个人收藏',summary:'这是格式示例，请替换为真实的网站与自己的观察。',tags:['格式示例'],patterns:['目录导航'],styles:['极简'],takeaways:['说明具体的信息组织方式，并记录适用场景。'],caution:'此条目仅演示扩展协议。',recipe:r.id,theme:'editorial'};bridge.download(JSON.stringify({kind:CASE_PACK_KIND,schemaVersion:1,cases:[c],recipes:[r],user:{notes:{},favorites:[]}},null,2),'design-atlas.case-pack.example.json','application/json');}
 function schema(){show(top('CASE PACK / VERSION 1','扩展协议','可以添加数据与组合，无需修改界面代码。')+`<div class="case-schema"><p>顶层字段：<code>kind: "design-atlas.case-pack"</code>、<code>schemaVersion: 1</code>、<code>cases: []</code>、<code>recipes: []</code>、<code>user: {notes: {}, favorites: []}</code>。</p><p>自定义 ID 以 <code>user-</code> 开头。案例引用内置或同包配方；配方引用已注册模块，props 只接收该模块已定义的文本属性。导入不执行脚本或自动访问网址。</p><p>配方的 theme 可以是主题 ID，也可以是包含 id、accent、bg、surface、ink、muted、font、radius、space、style 的主题对象。下载示例包即可从一个完整样例开始。</p><h3>已注册模块</h3><div class="schema-tags">${BLOCKS.map(b=>`<code>${b.id}</code>`).join('')}</div><h3>内置配方</h3><div class="schema-tags">${RECIPES.map(r=>`<code>${r.id}</code>`).join('')}</div><button class="primary-button" data-case-action="sample">下载可导入的示例包 ↓</button></div>`);}
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.caseRemove){const id=b.dataset.caseRemove,next=copyJSON(pack);next.cases=next.cases.filter(c=>c.id!==id);next.user.favorites=next.user.favorites.filter(x=>x!==id);delete next.user.notes[id];if(commit(next,'案例已移除，可在扩充我的库中撤销。'))render();return}
 if(b.dataset.recipeRemove){const id=b.dataset.recipeRemove;if(pack.cases.some(c=>c.recipe===id)){bridge.toast('还有自定义案例使用这个配方，请先编辑案例的配方选择。',true);return}const next=copyJSON(pack);next.recipes=next.recipes.filter(r=>r.id!==id);if(commit(next,'配方已移除，可在扩充我的库中撤销。'))render();return}
 if(b.dataset.caseOpen){open(b.dataset.caseOpen);return}if(b.dataset.caseFavorite){toggle(b.dataset.caseFavorite);return}if(b.dataset.caseCompare){const id=b.dataset.caseCompare;if(view.compare.includes(id))view.compare=view.compare.filter(x=>x!==id);else if(view.compare.length>=3){bridge.toast('最多同时比较 3 个案例，请先移除一个。');return}else view.compare.push(id);updateGrid();if(dialog.open&&preview?.case?.id===id)b.textContent=view.compare.includes(id)?'从对比移除':'加入对比';return}
 if(b.dataset.casePattern){view.pattern=b.dataset.casePattern;view.tab='cases';view.page=1;bridge.navigate();return}if(b.dataset.casePage){view.page=Number(b.dataset.casePage);updateGrid();$('.case-filter-controls')?.scrollIntoView({block:'start'});return}if(b.dataset.caseTab){view.tab=b.dataset.caseTab;render();return}
 if(b.dataset.caseDevice){const stage=$('.case-preview-stage',dialog);if(stage)stage.dataset.device=b.dataset.caseDevice;$$('[data-case-device]',dialog).forEach(x=>x.setAttribute('aria-pressed',x===b));return}
 if(b.dataset.caseSaveNote){const next=copyJSON(pack);next.user.notes[b.dataset.caseSaveNote]=$('#case-note').value;commit(next,'学习笔记已保存。');return}if(b.dataset.caseEdit){edit(b.dataset.caseEdit);return}
 if(b.dataset.caseRecipePreview){openRecipe(b.dataset.caseRecipePreview);return}
 if(b.dataset.caseRecipeApply){const r=recipes().find(r=>r.id===b.dataset.caseRecipeApply);if(r)bridge.apply(r,b.dataset.caseMode);return}
 if(b.dataset.caseCompareApply){const c=find(b.dataset.caseCompareApply);if(c){const r={...copyJSON(recipeFor(c)),theme:c.theme};if(bridge.apply(r,b.dataset.caseMode))close()}return}
 if(b.dataset.caseApply&&preview){const r=selectedRecipe();if(bridge.apply(r,b.dataset.caseApply))close();return}
 const a=b.dataset.caseAction;if(!a)return;
 if(a==='undo-pack'){if(packUndo){const before=packUndo;if(commit(before,'最近一次库修改已撤销。',{record:false})){packUndo=null;render()}}}else if(a==='close')close();else if(a==='add')edit();else if(a==='compare')compare();else if(a==='reset'){Object.assign(view,{q:'',type:'',style:'',pattern:'',sort:'recommended',favoriteOnly:false,page:1});render()}else if(a==='favorites'){view.favoriteOnly=!view.favoriteOnly;view.page=1;render()}else if(a==='capture')capture();else if(a==='import')file.click();else if(a==='export')bridge.download(JSON.stringify(pack,null,2),'design-atlas.my-cases.json','application/json');else if(a==='sample')sample();else if(a==='schema')schema();else if(a==='recovery-backup')bridge.download(localStorage.getItem(recoveryBackup)||'{}','design-atlas.recovery-backup.json','application/json');else if(a==='raw-backup')bridge.download(localStorage.getItem(CASE_STORAGE)||'{}','design-atlas.case-data.backup.json','application/json');else if(a==='code'&&preview){const p=bridge.makeProject(selectedRecipe());close();bridge.openCode(p)}
 });
 document.addEventListener('input',e=>{if(e.target.id==='case-search'){view.q=e.target.value;view.page=1;updateGrid()}});
 document.addEventListener('change',e=>{const k=e.target.dataset.caseFilter;if(k){view[k]=e.target.value;view.page=1;updateGrid()}if(e.target.id==='case-theme-select'&&preview){preview.themeTouched=true;previewDoc()}if(e.target.id==='case-recipe-select'&&preview){const r=recipes().find(r=>r.id===e.target.value);preview.themeTouched=false;preview.case=null;if(r)$('#case-theme-select').value=typeof r.theme==='string'?r.theme:r.theme.id;previewDoc()}});
 document.addEventListener('submit',e=>{const form=e.target;if(form.id==='case-edit-form'){e.preventDefault();try{const data=new FormData(form),split=k=>String(data.get(k)||'').split(/[,，\n]/).map(x=>x.trim()).filter(Boolean),id=form.dataset.editId||'user-'+uid();const raw={id,name:data.get('name'),url:data.get('url'),type:data.get('type'),category:data.get('category'),summary:data.get('summary'),styles:split('styles'),patterns:split('patterns'),tags:split('tags'),takeaways:split('takeaways'),caution:data.get('caution'),recipe:$('#edit-case-recipe').value,theme:$('#edit-case-theme').value};const c=validateCase(raw,registry,recipes(),'case',true),next=copyJSON(pack),index=next.cases.findIndex(x=>x.id===id);if(index<0)next.cases.push(c);else next.cases[index]=c;if(commit(next,'案例已保存到你的库。')){close();view.tab='cases';Object.assign(view,{q:c.name,type:'',style:'',pattern:'',favoriteOnly:false,page:1});bridge.navigate()}}catch(err){bridge.toast('保存失败：'+err.message,true)}}
 if(form.id==='recipe-capture-form'){e.preventDefault();const p=bridge.getProject(),data=new FormData(form),next=copyJSON(pack);next.recipes.push({id:'user-'+uid(),name:data.get('name'),description:data.get('description'),theme:p.theme,blocks:p.blocks.filter(b=>!b.hidden).map(b=>b.style&&Object.keys(b.style).length?{type:b.type,props:{...b.props},style:{...b.style}}:{type:b.type,props:{...b.props}})});if(commit(next,'当前页面已保存成可复用的配方。')){close();view.tab='recipes';bridge.navigate()}}
 });
 file.addEventListener('change',async()=>{const f=file.files[0];file.value='';if(!f)return;try{if(f.size>CASE_LIMITS.bytes)throw Error('扩展包最多 4 MiB');importPack(JSON.parse(await f.text()))}catch(e){bridge.toast('导入失败：'+e.message,true)}});
 document.addEventListener('keydown',e=>{if(e.key==='/'&&visible&&!$$('dialog[open]').length&&!/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)){e.preventDefault();$('#case-search')?.focus()}});
 dialog.addEventListener('close',()=>{document.body.style.overflow=$$('dialog[open]').length?'hidden':'';preview=null});
 dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
 return {load(data){if(data){if(data.version!==1||!Array.isArray(data.cases))throw Error('网站案例库格式错误');builtins=data.cases.map((c,i)=>validateCase(c,registry,RECIPES,`内置案例[${i}]`));if(new Set(builtins.map(c=>c.id)).size!==builtins.length)throw Error('内置案例 ID 重复')}},render,hide(){visible=false},open,card,items,isFavorite,toggle,favoriteCount:()=>pack.user.favorites.filter(id=>find(id)).length,setError(message){loadWarning=message},recipes,capture};
}
